# cli.sh — checks the command line: options, exit status, messages.
#
# Usage: cli.sh CSM WORKDIR FAKE_CLAUDE

CSM=$(cd "$(dirname "$1")" && pwd)/$(basename "$1")
WORK=$(cd "$2" && pwd)
FAKE_CLAUDE=$(cd "$(dirname "$3")" && pwd)/$(basename "$3")
CHECKS=0
FAILURES=0

# Relative paths in the checks below point into WORK, never elsewhere.
cd "$WORK" || exit 1
HOME=$WORK/home
CLAUDE_CONFIG_DIR=$HOME/.claude
LC_ALL=en_US.UTF-8
# Claude Code may well be running; the tests look for a process that is not.
CSM_CLAUDE_PROCESS=csm-no-such-process
export HOME CLAUDE_CONFIG_DIR LC_ALL CSM_CLAUDE_PROCESS
mkdir -p "$CLAUDE_CONFIG_DIR"

# expect STATUS PATTERN ARG... — runs csm, checks the exit status and that
# stdout+stderr match the grep pattern (an empty pattern means no output).
expect() {
	STATUS=$1
	PATTERN=$2
	shift 2
	CHECKS=$((CHECKS + 1))
	OUT=$("$CSM" "$@" 2>&1)
	GOT=$?
	if [ "$GOT" -ne "$STATUS" ]
	then
		FAILURES=$((FAILURES + 1))
		echo "cli: csm $*: status $GOT, want $STATUS"
		return
	fi
	if [ -z "$PATTERN" ]
	then
		if [ -n "$OUT" ]
		then
			FAILURES=$((FAILURES + 1))
			echo "cli: csm $*: unexpected output: $OUT"
		fi
		return
	fi
	if ! printf '%s\n' "$OUT" | grep -q -- "$PATTERN"
	then
		FAILURES=$((FAILURES + 1))
		echo "cli: csm $*: output does not match \"$PATTERN\": $OUT"
	fi
}

expect 0 '^csm [0-9]' -V
expect 0 '^csm [0-9]' --version
expect 0 '^Usage:' -h
expect 0 '^Usage:' --help
expect 0 '^csm -m \[-n\]' -m -h
expect 0 '^csm -m \[-n\]' -mh
expect 0 '^csm -m \[-n\]' --move --help
expect 0 '^csm -r \[-ny\]' -r a --help
expect 0 '^csm -l \[-oj\]' -h -l
expect 0 '^csm -s PATH' -s -h
expect 0 '^csm -F \[-n\]' -Fh
expect 0 '^csm -u \[-n\] \[ENTRY\]' -u -h
expect 0 '^csm -E \[-ny\]' --empty --help
expect 0 '^csm -P \[-ny\]' --prune --help

expect 1 "^csm: there is no directory “$WORK/a”" -mn a b
expect 1 '^csm: with several sources, “c” must be an existing directory' -m a b c
expect 1 'there is no directory' a --move --dry-run b
expect 1 "^csm: there is no directory “$WORK/new” — give" -F -n -- -old new
expect 1 '^csm: there are no sessions for “a”' -rny a
expect 1 'there are no sessions for “a”' --remove --yes --dry-run a
expect 1 '^csm: the trash has no entry “a” — “csm -u” lists' -un a
expect 1 '^csm: the trash has no entry “\.\./x”' -Ey ../x
expect 0 '^The trash is empty\.$' -u
expect 0 '^The trash is empty\.$' --restore --dry-run
expect 0 '^The trash is empty\.$' -En
expect 0 '^No saved GitHub repository path is missing\.$' -Pn
expect 2 "^csm: the full-screen interface needs a terminal — “csm -l” lists"

expect 2 '^csm: there is no option “-x”' -x
expect 2 '^csm: there is no option “--nope”' -m --nope=1 a b
expect 2 '^csm: option “--yes” does not take a value' -r --yes=1 a
expect 2 '^csm: there is no option “--dry”' -m --dry a b
expect 2 '^csm: option “-n” does not work with “-l”' -l -n
expect 2 '^csm: option “-y” does not work with “-m”' --move --yes a b
expect 2 'see “csm -m -h”' -m a
expect 2 '^csm: options “-l” and “-m” cannot be used together' -m -l
expect 2 '^csm: options “-s” and “-r” cannot be used together' -rs a
expect 2 '^csm: say what to do' -n
expect 2 '^csm: say what to do' list
expect 2 '^csm: say what to do' a b
expect 2 '^csm: say what to do' -- -l
expect 2 '^csm: wrong number of arguments for “-m”' -m a
expect 2 '^csm: wrong number of arguments for “-F”' -F a b c
expect 2 '^csm: wrong number of arguments for “-s”' -s
expect 2 '^csm: wrong number of arguments for “-r”' -ry
expect 2 '^csm: wrong number of arguments for “-l”' -l x
expect 2 '^csm: wrong number of arguments for “-u”' -u a b
expect 2 '^csm: option “-y” does not work with “-u”' -uy a
expect 2 '^csm: options “-r” and “-u” cannot be used together' -ru a
expect 2 '^csm: options “-u” and “-E” cannot be used together' -E --restore
# Without --yes the question needs a terminal; -n asks nothing.
expect 2 '^csm: there is no terminal to ask for confirmation — add “--yes” for “-r”' -r a < /dev/null
expect 2 'add “--yes” for “-E”' --empty x < /dev/null
expect 2 'add “--yes” for “-P”' -P < /dev/null
expect 2 '^csm: options “-E” and “-P” cannot be used together' -P -E
expect 2 '^csm: option “-o” does not work with “-P”' -Po
expect 1 'there are no sessions for “a”' -rn a < /dev/null
expect 2 '^csm: wrong number of arguments for “-l”' -l -- -m
expect 2 '^csm: option “-j” does not work with “-s”' -s -j x
expect 2 '^csm: option “-y” does not work with “-l”' -ly

# csm -l and csm -s on an empty config, then on three session directories:
# an active project, an orphaned one, one with nothing but memory/.
expect 0 '^There are no session directories in “~/.claude/projects”' -l
expect 0 '^\]$' -loj
expect 0 '^\]$' --list --orphans --json
expect 1 '^csm: there are no sessions for “x”' -s x
PROJ=$CLAUDE_CONFIG_DIR/projects
mkdir -p "$HOME/repo" "$PROJ/-repo" "$PROJ/-gone" "$PROJ/-mem/memory"
printf '{"type":"user","cwd":"%s","gitBranch":"main","timestamp":"2026-10-27T20:00:00Z","message":{"content":"hello there"}}\n' \
    "$HOME/repo" > "$PROJ/-repo/s1.jsonl"
printf '{"type":"user","cwd":"%s","message":{"content":"bye"}}\n' \
    "$HOME/gone" > "$PROJ/-gone/s2.jsonl"
expect 0 '^STATE  *SESSIONS  *SIZE  *LAST CHANGE  *PROJECT$' -l
expect 0 '^active  *1  *[0-9.]* B  .*  ~/repo$' -l
expect 0 '^orphaned  *1 .*  ~/gone$' --list
expect 0 '^unknown  *0  *0 B  .*  -mem$' -l
expect 0 '~/gone$' -lo
expect 0 '"path":"'"$HOME"'/gone","state":"orphan","sessions":1' -lj
expect 0 '"dir":"-mem","path":null,"state":"unknown"' -lj
expect 0 '^Project: ~/repo$' -s "$HOME/repo"
expect 0 '^State: active$' -s "$HOME/repo"
expect 0 'main  *hello there$' -s "$HOME/repo"
expect 0 '^Session directory: -gone$' -s -- -gone
expect 0 '^Project: –$' -s -- -mem
expect 1 '^csm: there are no sessions for “nowhere”' -s nowhere

# -o leaves out all but the orphaned ones.
CHECKS=$((CHECKS + 1))
if "$CSM" -lo | grep -q '~/repo'
then
	FAILURES=$((FAILURES + 1))
	echo "cli: csm -lo: shows an active project"
fi

if command -v jq > /dev/null 2>&1
then
	CHECKS=$((CHECKS + 1))
	if [ "$("$CSM" -lj | jq length)" != 3 ]
	then
		FAILURES=$((FAILURES + 1))
		echo "cli: csm -lj: not a JSON array of three"
	fi
fi

# githubRepoPaths keeps a path that is gone: -P plans, asks, takes it out.
printf '{"githubRepoPaths":{"o/r":["%s","%s"]}}\n' "$HOME/repo" \
    "$HOME/gone" > "$CLAUDE_CONFIG_DIR/.claude.json"
expect 0 '^goes: ~/gone (o/r)$' -Pn
expect 0 'Nothing has changed' --prune --dry-run
expect 1 '^csm: the configuration has no paths of the GitHub repository “o/x”' -Pn o/x
expect 1 '^goes: ~/gone (o/r)$' -Pn o/x O/R

# An orphaned project gets the places it may be now: here another path
# of its GitHub repository.
expect 0 '^Possible new places — “csm -F” moves the sessions there:$' \
    -s -- -gone
expect 0 '^  ~/repo$' -s -- -gone
CHECKS=$((CHECKS + 1))
if "$CSM" -s "$HOME/repo" | grep -q 'Possible new places'
then
	FAILURES=$((FAILURES + 1))
	echo "cli: csm -s: candidates for an active project"
fi

mkdir -p repo moved "$HOME/taken/repo"
expect 1 '^csm: “~/taken/repo” already exists' -m repo "$HOME/taken"
expect 1 'cannot be moved into itself' -m repo repo/inner
expect 1 "^csm: there is no directory “$WORK/nowhere”" -m repo nowhere/repo
expect 1 "^csm: “$WORK/moved” still exists" -F moved repo
expect 0 'Nothing has changed' -mn repo moved
expect 0 '(sessions only)' -Fn gone repo

# tests/sleeper.c plays Claude Code for a few seconds and ends by itself:
# changes wait for it, plans do not.
"$FAKE_CLAUDE" 5 &
CSM_CLAUDE_PROCESS=csm-fake-claude
expect 3 '^csm: Claude Code is running' -m repo moved
expect 3 '^csm: Claude Code is running' -F gone repo
expect 3 '^csm: Claude Code is running' -ry repo
expect 3 '^csm: Claude Code is running' -u entry
expect 3 '^csm: Claude Code is running' -Py
expect 0 '^goes: ~/gone' -Pn
expect 0 '^The trash is empty\.$' -u
expect 0 '^The trash is empty\.$' -Ey
expect 0 '^Usage:' -h
expect 0 'Nothing has changed' -Fn gone repo
CSM_CLAUDE_PROCESS=csm-no-such-process

LC_ALL=pl_PL.UTF-8
expect 0 '^Użycie:' --help
expect 2 '^csm: nie ma opcji „-x”' -x
expect 1 "^csm: nie ma katalogu „$WORK/a”" -mn a b
expect 1 '^csm: „~/taken/repo” już istnieje' -m repo "$HOME/taken"
expect 0 'Nic nie zostało zmienione' -mn repo moved
expect 0 '^STAN  *SESJE  *ROZMIAR  *OSTATNIA ZMIANA  *PROJEKT$' -l
expect 0 '^osierocony  *1 .*  ~/gone$' -lo
expect 0 '^Stan: aktywny$' -s "$HOME/repo"
expect 0 '^Możliwe nowe miejsca — „csm -F” przenosi tam sesje:$' -s -- -gone
expect 1 '^csm: nie ma sesji dla „nowhere”' -s nowhere
expect 0 '^Kosz jest pusty\.$' -u
expect 2 '^csm: bez terminala nie ma kogo zapytać o zgodę — dodaj „--yes”' -r nowhere < /dev/null
expect 1 '^csm: w koszu nie ma wpisu „x”' -u x
expect 2 "^csm: interfejs pełnoekranowy potrzebuje terminala" < /dev/null
expect 0 '^znika: ~/gone (o/r)$' -Pn
CSM_CLAUDE_PROCESS=csm-fake-claude
expect 3 '^csm: Claude Code działa' -F gone repo
CSM_CLAUDE_PROCESS=csm-no-such-process
wait
LC_ALL=C
expect 0 '^Usage:' -h
expect 0 '^Removed from the configuration' -Py o/r
expect 0 '^No saved GitHub repository path is missing\.$' -Py
CHECKS=$((CHECKS + 1))
if grep -q gone "$CLAUDE_CONFIG_DIR/.claude.json" ||
    ! grep -q gone "$CLAUDE_CONFIG_DIR/.claude.json.bak"
then
	FAILURES=$((FAILURES + 1))
	echo "cli: csm -Py: .claude.json or its .bak is wrong"
fi

# Messages go to stderr, nothing to stdout.
CHECKS=$((CHECKS + 1))
if [ -n "$("$CSM" -x 2>/dev/null)" ]
then
	FAILURES=$((FAILURES + 1))
	echo "cli: csm -x: error message on stdout"
fi

echo "cli: $CHECKS checks, $FAILURES failed"
[ "$FAILURES" -eq 0 ]
